function cholLevelLDL(x){ if(x<100)return '理想'; if(x<130)return '接近理想'; if(x<160)return '临界高'; if(x<190)return '高'; return '极高'; }
function cholLevelHDL(x){ if(x<40)return '偏低（风险）'; if(x<60)return '正常'; return '偏高（保护）'; }
function cholLevelTG(x){ if(x<150)return '正常'; if(x<200)return '临界高'; if(x<500)return '高'; return '极高'; }
function cholesterolEval(ldl, hdl, tg){
  ldl=+ldl; hdl=+hdl; tg=+tg;
  if(!(ldl>=0)||!(hdl>=0)||!(tg>=0)) return {error:'数值须为非负数字'};
  var total=Math.round(ldl+hdl+tg/5);
  var lvLDL=cholLevelLDL(ldl), lvHDL=cholLevelHDL(hdl), lvTG=cholLevelTG(tg);
  var risk = (ldl>=190||tg>=500)?'高风险':((ldl>=160||hdl<40||tg>=200)?'中风险':'低风险');
  return {total:total, ldl:ldl, ldlLevel:lvLDL, hdl:hdl, hdlLevel:lvHDL, tg:tg, tgLevel:lvTG, risk:risk};
}
var EXPORTS={cholesterolEval:cholesterolEval, cholLevelLDL:cholLevelLDL, cholLevelHDL:cholLevelHDL, cholLevelTG:cholLevelTG};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CholesterolForgePure = EXPORTS; }
